package steps

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	const (
		// command is the double command of the declared Calculator CLI; the
		// step's capture is its one required VALUE argument.
		command = "double"
		// wantCaptures is the pattern's single capture, the whole number.
		wantCaptures = 1
	)

	if len(args) != wantCaptures {
		return fmt.Errorf("doubling: the step gave %d captures, want %d", len(args), wantCaptures)
	}

	value := args[0]

	if state.Program == "" || state.HostRoot == "" {
		return fmt.Errorf("doubling: no calculator program is installed, so %s %s cannot be run", command, value)
	}

	// The binding runs the kept program as a process from the host root,
	// passing the step's whole number as VALUE. The inherited environment
	// carries this run's Go cache and temporary directory.
	run := exec.Command(state.Program, command, value)
	run.Dir = state.HostRoot
	run.Env = os.Environ()

	var stdout, stderr bytes.Buffer

	run.Stdout = &stdout
	run.Stderr = &stderr

	err := run.Run()
	if err != nil {
		return fmt.Errorf("doubling: %s %s %s in %s: %w\n%s",
			state.Program, command, value, state.HostRoot, err, stderr.String())
	}

	// The CLI document declares exit 0 prints the doubled integer and a
	// newline. The step only reads that integer; it never works out what
	// the double of the number should be.
	printed := strings.TrimSpace(stdout.String())

	doubled, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf("doubling: %s %s %s printed %q on stdout, not the integer the CLI document declares: %w",
			state.Program, command, value, stdout.String(), err)
	}

	state.Result = doubled
	state.Doubled = true

	return nil
}

package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

//truebdd:concept given "installation"
func conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c(state *State, args []string) error {
	const (
		// servicePackage and the go build that follows are what the CLI
		// document declares the calculator is built from, at the host root.
		servicePackage = "./services/calc"
		// buildSubdir keeps the program under the host's tmp directory, as
		// the binding's does clause requires. A fixed name rather than a
		// fresh temp dir: a step gets no *testing.T to register cleanup
		// with, and the suite's scenarios run sequentially, so re-using one
		// directory leaves one program behind instead of one per run.
		buildSubdir  = "tmp/bdd-calc"
		programName  = "calc"
		buildDirPerm = 0o755
	)

	start, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("installation: locating the working directory: %w", err)
	}

	// The host project root is the nearest enclosing directory with a
	// go.mod — the module the suite belongs to. Decided by go.mod and not
	// by looking for the service's directory, so a host project copied
	// without its service still resolves to its own root and the search
	// never climbs out of the module to find one elsewhere.
	hostRoot := ""
	dir := start

	for {
		_, statErr := os.Stat(filepath.Join(dir, "go.mod"))
		if statErr == nil {
			hostRoot = dir

			break
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}

		dir = parent
	}

	if hostRoot == "" {
		return fmt.Errorf("installation: no go.mod at or above %s, so the host project root is unknown", start)
	}

	buildDir := filepath.Join(hostRoot, buildSubdir)

	err = os.MkdirAll(buildDir, buildDirPerm)
	if err != nil {
		return fmt.Errorf("installation: preparing the build directory %s: %w", buildDir, err)
	}

	program := filepath.Join(buildDir, programName)

	build := exec.Command("go", "build", "-o", program, servicePackage)
	build.Dir = hostRoot
	// The inherited environment carries the Go build cache and temporary
	// directory this test run was given; the build must use those.
	build.Env = os.Environ()

	output, err := build.CombinedOutput()
	if err != nil {
		return fmt.Errorf("installation: go build -o %s %s in %s: %w\n%s",
			program, servicePackage, hostRoot, err, output)
	}

	state.HostRoot = hostRoot
	state.Program = program

	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

//truebdd:concept then "result"
func concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e(state *State, args []string) error {
	const (
		// command is the double command of the declared Calculator CLI, whose
		// stdout the doubling When kept for this Then to observe.
		command = "double"
		// wantCaptures is the pattern's single capture, the expected whole
		// number as written in the step.
		wantCaptures = 1
	)

	if len(args) != wantCaptures {
		return fmt.Errorf("result: the step gave %d captures, want %d", len(args), wantCaptures)
	}

	// The capture is an optional minus sign followed by digits, so it reads
	// back as the whole number the step wrote. This is the step's own
	// expectation, not anything worked out from the number that was doubled.
	expected, err := strconv.Atoi(args[0])
	if err != nil {
		return fmt.Errorf("result: the step's expected whole number %q is not an integer: %w", args[0], err)
	}

	if !state.Doubled {
		return fmt.Errorf("result: the %s command was not run, so there is no printed whole number to compare with %d",
			command, expected)
	}

	// The observation is the integer the CLI document declares the double
	// command prints on stdout, as the When read and kept it. The comparison
	// is the whole of this step's work: it never doubles anything itself.
	if state.Result != expected {
		return fmt.Errorf("result: the %s command printed %d on stdout, want %d",
			command, state.Result, expected)
	}

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("^the calculator (?:is|has been) installed$", conceptbef0930c9a09dec2b565c664833e27eb5e85810f2e50d51372923cf970aa997c)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)

	suite.Step("^the result is (-?\\d+)$", concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e)
}

package steps

// State is what one scenario's calc steps share.
type State struct {
	// HostRoot is the host project's root — the directory holding the
	// go.mod of the module under test — located by the installation Given.
	// It is the directory the calculator program is run from.
	HostRoot string
	// Program is the path of the calculator program the installation Given
	// built under the host's tmp directory.
	Program string
	// Result is the integer the calculator's double command printed on
	// stdout, kept by the doubling When for the result Then to observe.
	Result int
	// Doubled records that the doubling When ran the double command and
	// kept its stdout, so the result Then can tell a printed 0 apart from
	// no run at all.
	Doubled bool
}
